-- ============================================================
-- TAMBAHAN KURSUS ORGANIZATION DESIGN (4 kursus, MASING-MASING 5 BAGIAN, BERURUTAN)
-- Tiap kursus: 5 video bagian + kuis per bagian + materi PDF, plus Tes Lewati (placement).
-- Media menunjuk ke folder 'public/'. Idempoten: mereset isi keempat kursus lalu mengisi ulang.
-- Jalankan SETELAH 01-05 (dan boleh sebelum/sesudah 07).
-- ============================================================
set check_function_bodies = off;

-- Reset isi keempat kursus (hindari sisa versi lama)
delete from public.assessment_attempts where assessment_id in (select id from public.assessments where course_id in ('1d000000-0000-0000-0000-000000000002','1d000000-0000-0000-0000-000000000003','1d000000-0000-0000-0000-000000000004','1d000000-0000-0000-0000-000000000005'));
delete from public.questions where assessment_id in (select id from public.assessments where course_id in ('1d000000-0000-0000-0000-000000000002','1d000000-0000-0000-0000-000000000003','1d000000-0000-0000-0000-000000000004','1d000000-0000-0000-0000-000000000005'));
delete from public.assessments where course_id in ('1d000000-0000-0000-0000-000000000002','1d000000-0000-0000-0000-000000000003','1d000000-0000-0000-0000-000000000004','1d000000-0000-0000-0000-000000000005');
delete from public.video_questions where lesson_id in (select l.id from public.lessons l join public.modules m on l.module_id=m.id where m.course_id in ('1d000000-0000-0000-0000-000000000002','1d000000-0000-0000-0000-000000000003','1d000000-0000-0000-0000-000000000004','1d000000-0000-0000-0000-000000000005'));
delete from public.lesson_progress where lesson_id in (select l.id from public.lessons l join public.modules m on l.module_id=m.id where m.course_id in ('1d000000-0000-0000-0000-000000000002','1d000000-0000-0000-0000-000000000003','1d000000-0000-0000-0000-000000000004','1d000000-0000-0000-0000-000000000005'));
delete from public.lessons where module_id in (select id from public.modules where course_id in ('1d000000-0000-0000-0000-000000000002','1d000000-0000-0000-0000-000000000003','1d000000-0000-0000-0000-000000000004','1d000000-0000-0000-0000-000000000005'));
delete from public.modules where course_id in ('1d000000-0000-0000-0000-000000000002','1d000000-0000-0000-0000-000000000003','1d000000-0000-0000-0000-000000000004','1d000000-0000-0000-0000-000000000005');
delete from public.enrollments where course_id in ('1d000000-0000-0000-0000-000000000002','1d000000-0000-0000-0000-000000000003','1d000000-0000-0000-0000-000000000004','1d000000-0000-0000-0000-000000000005');
delete from public.course_competencies where course_id in ('1d000000-0000-0000-0000-000000000002','1d000000-0000-0000-0000-000000000003','1d000000-0000-0000-0000-000000000004','1d000000-0000-0000-0000-000000000005');

