 ('5d310000-0000-0000-0000-000000000002','00000000-0000-0000-0000-0000000000a1','4d000030-0000-0000-0000-000000000001','true_false','Star Model menekankan keselarasan, bukan sekadar bagan yang rapi.','["Benar", "Salah"]'::jsonb,'"Benar"'::jsonb,1,1),
 ('5d320000-0000-0000-0000-000000000001','00000000-0000-0000-0000-0000000000a1','4d000030-0000-0000-0000-000000000002','mcq','Titik awal desain dalam Star Model adalah...','["Struktur", "Strategi", "Imbalan", "Orang"]'::jsonb,'"Strategi"'::jsonb,1,0),
 ('5d320000-0000-0000-0000-000000000002','00000000-0000-0000-0000-0000000000a1','4d000030-0000-0000-0000-000000000002','true_false','Strategi memandu keempat titik lainnya.','["Benar", "Salah"]'::jsonb,'"Benar"'::jsonb,1,1),
