 ('5d330000-0000-0000-0000-000000000002','00000000-0000-0000-0000-0000000000a1','4d000030-0000-0000-0000-000000000003','true_false','Struktur menetapkan di mana keputusan diambil.','["Benar", "Salah"]'::jsonb,'"Benar"'::jsonb,1,1),
